#include <stdio.h>
#include <string.h>

int main(void) {
    char s[256];
    if (scanf("%255s", s) != 1) return 1;
    unsigned int dai = (unsigned int)strlen(s);
    printf("%02X %02X", (dai >> 8) & 0xFF, dai & 0xFF);
    for (size_t i = 0; i < strlen(s); i++) printf(" %02X", (unsigned char)s[i]);
    printf("\n");
    return 0;
}
